import{_ as s,o as n,c as i,a3 as r,j as e,a as o,t as d}from"./chunks/framework.BTQ4eCVb.js";const f=JSON.parse('{"title":"Automation","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Automation | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/automation"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Automation | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/automation"}]]},"headers":[],"relativePath":"user-guide/automation.md","filePath":"user-guide/automation.md","lastUpdated":1788828624000}'),l={name:"user-guide/automation.md"};function u(a,t,c,g,p,m){return n(),i("div",null,[t[3]||(t[3]=r('<h1 id="automation" tabindex="-1">Automation <a class="header-anchor" href="#automation" aria-label="Permalink to &quot;Automation&quot;">​</a></h1><p>Workflow Automation lets your workspace react to CRM and operations events without custom code.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ol><li>Open <strong>Marketplace</strong> and install <strong>Automation</strong> (billable add-on).</li><li>Ensure your role includes Automation permissions (Admin gets full access by default).</li><li>Install any <strong>business modules</strong> the journey needs (for example Leads + Tasks, or Help Desk + Tasks).</li><li>Open <strong>Automation</strong> in the <strong>Operations</strong> sidebar section.</li></ol><h2 id="build-a-workflow" tabindex="-1">Build a workflow <a class="header-anchor" href="#build-a-workflow" aria-label="Permalink to &quot;Build a workflow&quot;">​</a></h2><ol><li><strong>New</strong> or pick a <strong>Template</strong>.</li><li>Choose a <strong>trigger</strong>. Triggers for modules you have not installed are marked <strong>Module not installed</strong> and cannot be activated until that module is entitled.</li><li>For <strong>Schedule</strong>, set frequency (daily / weekly / monthly / cron) and time in the <strong>workspace timezone</strong>.</li><li>Add optional <strong>conditions</strong> — pick fields from the trigger’s payload (AND or OR groups).</li><li>Add one or more <strong>actions</strong> in order. People, tags, and stages use searchable pickers; notify supports <strong>multiple recipients</strong> including <strong>Record assignee (from trigger)</strong>.</li><li>For <strong>Create task</strong> on a Lead trigger, optionally tick <strong>Also create a lead follow-up</strong> (off by default; templates may enable it).</li><li><strong>Save</strong> (inactive) or <strong>Save &amp; activate</strong>. Only active workflows run.</li></ol><h3 id="manual-run" tabindex="-1">Manual Run <a class="header-anchor" href="#manual-run" aria-label="Permalink to &quot;Manual Run&quot;">​</a></h3><p>From the workflow list, <strong>Run</strong> opens a dialog. For event-style triggers pick a related record so actions receive assignee and entity context. Manual / Schedule triggers run without a related record.</p><h3 id="recipes-real-world-journeys" tabindex="-1">Recipes (real-world journeys) <a class="header-anchor" href="#recipes-real-world-journeys" aria-label="Permalink to &quot;Recipes (real-world journeys)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Recipe</th><th>Trigger</th><th>Typical actions</th><th>Modules</th></tr></thead><tbody><tr><td>New lead follow-up</td><td>Lead created</td><td>Create task + lead follow-up + notify</td><td>Automation, Leads, Tasks</td></tr><tr><td>High-priority task alert</td><td>Task created (priority = high)</td><td>Notify assignee</td><td>Automation, Tasks</td></tr><tr><td>Opportunity stage chase</td><td>Opportunity stage changed</td><td>Create follow-up task</td><td>Automation, Opportunities, Tasks</td></tr><tr><td>Invoice created follow-up</td><td>Customer invoice created</td><td>Task + notify</td><td>Automation, Invoices, Tasks</td></tr><tr><td>Payment posted notify</td><td>Customer payment posted</td><td>Notify AR owner</td><td>Automation, Payments</td></tr><tr><td>Credit note applied</td><td>Credit note applied</td><td>Notify assignee</td><td>Automation, Credit Notes</td></tr><tr><td>Help Desk SLA escalate</td><td>Help Desk SLA breached</td><td>Notify + escalate task</td><td>Automation, Help Desk, Tasks</td></tr><tr><td>WhatsApp inbound triage</td><td>WhatsApp message received</td><td>Notify (+ optional WA template)</td><td>Automation, WhatsApp Cloud</td></tr><tr><td>Contact welcome</td><td>Contact created</td><td>Welcome task + notify</td><td>Automation, Contacts, Tasks</td></tr><tr><td>Quotation follow-up</td><td>Quotation created</td><td>Follow-up task</td><td>Automation, Quotations, Tasks</td></tr><tr><td>Large expense alert</td><td>Expense created (amount ≥ 1000)</td><td>Notify</td><td>Automation, Expenses</td></tr><tr><td>Employee onboarding</td><td>Employee created</td><td>Onboarding task</td><td>Automation, Employees, Tasks</td></tr><tr><td>Project kickoff</td><td>Project created</td><td>Kickoff task + notify</td><td>Automation, Projects, Tasks</td></tr></tbody></table><p>Starter <strong>Templates</strong> seed the same journeys when the required modules are installed.</p><h3 id="triggers-v1-3" tabindex="-1">Triggers (v1.3) <a class="header-anchor" href="#triggers-v1-3" aria-label="Permalink to &quot;Triggers (v1.3)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Trigger family</th><th>When</th></tr></thead><tbody><tr><td>Manual / Schedule</td><td>You click Run, or workspace-timezone schedule</td></tr><tr><td>Leads / Tasks / Opportunities / Meetings</td><td>CRM lifecycle</td></tr><tr><td>Contacts / Quotations / Expenses / Employees</td><td>Stubbed triggers now wired</td></tr><tr><td>Invoices / Payments / Credit Notes</td><td>Billing lifecycle (invoice created; payment posted; credit applied)</td></tr><tr><td>Help Desk</td><td>Ticket created, status changed, SLA breached</td></tr><tr><td>WhatsApp Cloud</td><td>Inbound message received</td></tr><tr><td>Projects</td><td>Created, status changed, assigned</td></tr><tr><td>Estimates / Contracts / Purchase Orders</td><td>Created</td></tr><tr><td>Leave / Documents / Knowledge Base / Assets</td><td>Created</td></tr></tbody></table><h3 id="actions-v1" tabindex="-1">Actions (v1) <a class="header-anchor" href="#actions-v1" aria-label="Permalink to &quot;Actions (v1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Action</th><th>Notes</th></tr></thead><tbody><tr><td>Create task</td><td>Requires Tasks module. Defaults to <strong>record assignee</strong>. Always notes the triggering lead/opportunity/task; optional <strong>lead follow-up</strong> via <code>create_lead_follow_up</code>.</td></tr><tr><td>Create note</td><td>On lead / task / opportunity from the triggering entity</td></tr><tr><td>Assign user</td><td>Sets assignee on the triggering entity (picker)</td></tr><tr><td>Add / remove tag</td><td>Tag picker for the trigger’s module</td></tr><tr><td>Update field</td><td>Allowlisted fields for the trigger entity</td></tr><tr><td>Move stage</td><td>Stage picker (leads / opportunities)</td></tr><tr><td>Send notification</td><td>In-app; multi-recipient including record assignee; <code>source=workflow</code></td></tr><tr><td>Send WhatsApp template</td><td>Requires WhatsApp Cloud</td></tr><tr><td>Webhook</td><td>Signed outbound HTTP POST</td></tr><tr><td>Delay</td><td>Wait before the next step</td></tr></tbody></table>',15)),e("p",null,[t[0]||(t[0]=o("Use ",-1)),e("code",null,d(a.field),1),t[1]||(t[1]=o(" chips in titles/bodies (for example ",-1)),e("code",null,d(a.name),1),t[2]||(t[2]=o(") to insert values from the triggering record.",-1))]),t[4]||(t[4]=r('<h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><p>Use <strong>Templates</strong> to seed a draft workflow (inactive). The list only shows templates whose <strong>required modules</strong> are installed. Edit conditions/actions, then activate.</p><h2 id="runs" tabindex="-1">Runs <a class="header-anchor" href="#runs" aria-label="Permalink to &quot;Runs&quot;">​</a></h2><p><strong>Runs</strong> shows each execution with status and step logs. Failures keep an error message for troubleshooting. Manual <strong>Run</strong> is useful for testing.</p><h2 id="coexistence-with-built-in-lead-rules" tabindex="-1">Coexistence with built-in Lead rules <a class="header-anchor" href="#coexistence-with-built-in-lead-rules" aria-label="Permalink to &quot;Coexistence with built-in Lead rules&quot;">​</a></h2><p>Lead tag auto follow-ups and inactivity digests remain hard-coded product rules. They are <strong>not</strong> replaced by Automation in v1 — you can use both.</p><h2 id="timezone" tabindex="-1">Timezone <a class="header-anchor" href="#timezone" aria-label="Permalink to &quot;Timezone&quot;">​</a></h2><p>Schedule triggers use the workspace timezone from <strong>Settings → General</strong>. Absolute timestamps in run logs follow the same convention as other modules.</p>',8))])}const y=s(l,[["render",u]]);export{f as __pageData,y as default};
